import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { MouseEventData } from './mouse-tracker.service';

@Injectable({
  providedIn: 'root'
})
export class MouseDataService {
  private apiUrl = 'http://localhost:4000/test/mouse-data';

  constructor(private http: HttpClient) {}

  sendMouseData(testName: string, events: MouseEventData[], sessionId: string ): Observable<any> {
    const payload = {
      testName,
      events,
      sessionId
    };

    return this.http.post(this.apiUrl, payload);
  }
}
